using System.Security.Cryptography;
using System.Text;

namespace HondaEcu.Core.Tests;

[Collection(TimingSensitiveTestCollection.Name)]
public sealed class P28RpmPlannerOptimizationTests
{
    // Golden metadata was captured BEFORE the optimization, from the unmodified
    // planner source SHA-256:
    // 3cf6ffe2ab9319840ee99ffd5b1ca5d986beb26b82f20014e45cdf19e14113f5.
    // Frozen Core assembly SHA-256:
    // 3f1de269633ce25f5a2fac6debcbde668851543b8aeb038147d9095196bacf36.
    // Expected hashes are not generated by the optimized implementation. They
    // cover the COMPLETE serialized report, including all candidate intervals,
    // boundaries, reasons, assumptions, provenance, ordering and minimax ties.
    [Theory]
    [InlineData("desktop-strict")]
    [InlineData("desktop-both")]
    [InlineData("strict")]
    [InlineData("er1-only")]
    [InlineData("both-integral")]
    [InlineData("both-fractional")]
    [InlineData("overflow")]
    [InlineData("invalid-capture")]
    [InlineData("zero-envelope")]
    [InlineData("tie")]
    [InlineData("er3-only")]
    [InlineData("other-slot-prior-provenance")]
    [InlineData("missing")]
    public void CompleteReportsMatchTheUnoptimizedFrozenOracle(string name)
    {
        var expected = Before(name);
        AssertReport(expected, P28RpmPlanner.Analyze(Query(expected)));
    }

    [Fact]
    public void AlternatingSnapshotsNeverReuseAnotherQueriesResultOrAssumptions()
    {
        // Alternate scenarios, permission sets, slots/prior states and provenance,
        // then revisit earlier queries. Each call must match its own before-fix hash.
        foreach (var name in new[]
        {
            "desktop-both", "desktop-strict", "other-slot-prior-provenance",
            "er1-only", "both-fractional", "desktop-both", "desktop-strict",
        })
        {
            var expected = Before(name);
            AssertReport(expected, P28RpmPlanner.Analyze(Query(expected)));
        }
    }

    [Fact]
    public void AlreadyCancelledRequestsNeverPublishAnyPlanningResult()
    {
        using var cancellation = new CancellationTokenSource();
        cancellation.Cancel();
        foreach (var name in new[] { "desktop-strict", "desktop-both", "missing" })
        {
            var exception = Assert.Throws<OperationCanceledException>(() =>
                P28RpmPlanner.Analyze(Query(Before(name)), cancellation.Token));
            Assert.Equal(cancellation.Token, exception.CancellationToken);
        }
    }

    private static void AssertReport(OracleCase expected, P28RpmPlanningReport report)
    {
        Assert.Equal(expected.QueryDigest, report.Query.QueryDigest);
        Assert.Equal(expected.ReportHash, report.ComputeDigest());
        var canonicalHash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(report.ToJson(false)))).ToLowerInvariant();
        Assert.Equal(expected.ReportHash, canonicalHash);
        Assert.Equal(expected.Status, report.Status);
        Assert.False(report.PhysicalRpmAvailable);
        Assert.Equal("NotFlashReady", report.FlashReadiness);
        Assert.Equal("NotRun", report.ExecutionStatus);
        Assert.Equal("NotRun", report.HardwareStatus);
        Assert.Equal(expected.Best, report.BestCandidates.Select(candidate => candidate.RawValue));
        Assert.Equal(report.Inverse.Where(candidate => candidate.IsBest).Select(candidate => candidate.RawValue),
            report.BestCandidates.Select(candidate => candidate.RawValue));
        if (expected.Name == "missing")
        {
            Assert.Null(report.Forward);
            Assert.Null(report.SupportedNormalDomain);
            Assert.Empty(report.Inverse);
            Assert.Empty(report.UsedAssumptions);
            return;
        }

        Assert.Equal(256, report.Inverse.Count);
        Assert.Equal(Enumerable.Range(0, 256).Select(raw => (byte)raw), report.Inverse.Select(candidate => candidate.RawValue));
        Assert.Equal(new P28RpmInterval(expected.Desktop ? "625000/54613" : "60/54613",
            expected.Desktop ? "625000/1" : "60/1", true, true), report.SupportedNormalDomain);
        string[] used = expected.Assumptions.Contains(P28ProducerModel.AddEr1Assumption)
            ? expected.Assumptions : [];
        Assert.Equal(used, report.UsedAssumptions);
        Assert.All(report.Inverse, candidate => Assert.Equal(report.UsedAssumptions, candidate.UsedAssumptions));
        Assert.All(report.Forward!.Variants.Where(variant => variant.Producer is not null), variant => Assert.False(variant.Producer!.S));
        if (expected.Status is "Unresolved" or "InvalidRequestedDomain")
        {
            Assert.Empty(report.BestCandidates);
            Assert.All(report.Inverse, candidate => Assert.False(candidate.SimpleSelectable));
        }
        if (expected.Status == "Unresolved")
        {
            Assert.Equal("NotEstablishedUnresolvedOrNonmonotone", report.MonotonicityStatus);
            Assert.All(report.Inverse, candidate =>
            {
                Assert.Contains(candidate.Regions, region => region.State == P28RpmRegionState.Unknown);
                Assert.NotEmpty(candidate.IneligibilityReasons);
            });
        }
        foreach (var candidate in report.Inverse.Where(candidate => candidate.SimpleSelectable))
        {
            var mixed = Assert.Single(candidate.Regions.Where(region => region.State == P28RpmRegionState.Mixed));
            Assert.False(mixed.Interval.LowerInclusive);
            Assert.False(mixed.Interval.UpperInclusive);
            Assert.True(candidate.TransitionBand!.LowerInclusive);
            Assert.True(candidate.TransitionBand.UpperInclusive);
            Assert.Equal(mixed.Interval.Lower, candidate.TransitionBand.Lower);
            Assert.Equal(mixed.Interval.Upper, candidate.TransitionBand.Upper);
            Assert.Empty(candidate.IneligibilityReasons);
            Assert.NotNull(candidate.MinimaxError);
        }
        if (expected.Name == "tie")
        {
            Assert.Equal(new byte[] { 253, 254 }, report.BestCandidates.Select(candidate => candidate.RawValue));
            Assert.All(report.BestCandidates, candidate => Assert.Equal("27/620", candidate.MinimaxError));
            Assert.All(report.BestCandidates, candidate => Assert.True(candidate.IsBest));
        }
    }

    private static P28RpmQuery Query(OracleCase expected) =>
        P28RpmQuery.Create(expected.Name == "missing" ? null :
            P28RpmScenario.Parse(expected.Desktop ? DesktopScenarioJson : CoreScenarioJson),
            expected.SlotId, expected.OriginalRaw, expected.TargetRpm, expected.TargetProvenance, expected.Assumptions);

